require_once __DIR__ . '/_layout.php';requirePermission('reservations.manage');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:(int)($_POST['reservation_id']??0);$reservation=$id?scopedReservationRecord($id,false):null;if(!$reservation){http_response_code(404);exit(t('validation.reservation_not_found'));}
if(requestMethod()==='POST'){requireCsrfPost();try{updateReservationAllocation($reservation['id'],$_POST);flash('success',t('message.allocation_updated'));safeRedirect('reservation_detail.php?id='.$reservation['id'].'&tab=allocation');}catch(AuthorizationException$e){http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){flash('danger',$e->getMessage());}catch(Throwable$e){reportDatabaseError($e,'Reservation allocation update failed');flash('danger',t('message.allocation_failed'));}$reservation=scopedReservationRecord($id,false);}
$vehicles=dbFetchAll("SELECT id,registration_number,brand,model,status FROM vehicles WHERE agency_id=:agency AND archived_at IS NULL AND status NOT IN ('maintenance','damaged','blocked','sold','retired') ORDER BY registration_number",['agency'=>$reservation['agency_id']]);backofficeHeader(t('page.reservation_edit.title'),'reservation_edit.php');pageHeader('page.reservation_edit.title','page.reservation_edit.description',['breadcrumbs'=>[['label'=>'nav.reservations','href'=>'reservations.php'],['label'=>$reservation['reference'],'href'=>'reservation_detail.php?id='.$id],['label'=>'section.allocation_editor']],'secondary'=>['label'=>'common.cancel','href'=>'reservation_detail.php?id='.$id]]);?>
<section class="card form-card"><form method="post"><?=csrfField()?><input type="hidden" name="reservation_id" value="<?=e($id)?>"><input type="hidden" name="updated_at" value="<?=e($reservation['updated_at'])?>"><label><?=e(t('field.operation'))?><select name="mode"><option value="edit"><?=e(t('option.allocation_edit'))?></option><option value="extend"><?=e(t('option.extension'))?></option><option value="replace"><?=e(t('option.replacement'))?></option></select></label><label><?=e(t('field.vehicle'))?><select name="vehicle_id"><?php foreach($vehicles as$v):?><option value="<?=e($v['id'])?>" <?=(int)$reservation['vehicle_id']===(int)$v['id']?'selected':''?>><?=e($v['registration_number'].' — '.$v['brand'].' '.$v['model'].' — '.translatedStatus($v['status']))?></option><?php endforeach;?></select></label><label><?=e(t('field.pickup'))?><input type="datetime-local" name="pickup_at" value="<?=e(date('Y-m-d\TH:i',strtotime($reservation['pickup_at'])))?>" required></label><label><?=e(t('field.return_extension'))?><input type="datetime-local" name="return_at" value="<?=e(date('Y-m-d\TH:i',strtotime($reservation['return_at'])))?>" required></label><?php if(can('reservations.commercial_override')):?><fieldset><legend><?=e(t('section.commercial_override'))?></legend><p class="help"><?=e(t('message.override_optional'))?></p><label><?=e(t('field.override_daily_price'))?><input name="override_daily_price" inputmode="decimal"></label><label><?=e(t('field.reason'))?><input name="override_reason" maxlength="255"></label></fieldset><?php endif;?><button class="btn primary"><?=e(t('action.validate_allocation'))?></button></form></section><?php backofficeFooter();
